import{_ as a,o as t,c as r,a3 as e}from"./chunks/framework.qCVWde4n.js";const u=JSON.parse('{"title":"更新日志","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md","lastUpdated":null}'),l={name:"changelog.md"};function n(s,o,i,d,c,g){return t(),r("div",null,[...o[0]||(o[0]=[e('<h1 id="更新日志" tabindex="-1">更新日志 <a class="header-anchor" href="#更新日志" aria-label="Permalink to &quot;更新日志&quot;">​</a></h1><p>按版本倒序，记录每一版做了什么、修了什么、以及<strong>作者推翻过的判断</strong>。</p><div class="tip custom-block"><p class="custom-block-title">术语速查</p><ul><li><strong>小u</strong> —— 游戏内悬浮窗，点开是控制台面板</li><li><strong>落盘</strong> —— 写进文件，重启后还在</li><li><strong>挂钩</strong> —— 在游戏源码里插一段我们的代码</li></ul></div><h2 id="网站改版-v3-0-→-v4-8" tabindex="-1">网站改版（v3.0 → v4.8） <a class="header-anchor" href="#网站改版-v3-0-→-v4-8" aria-label="Permalink to &quot;网站改版（v3.0 → v4.8）&quot;">​</a></h2><blockquote><p>这一节记的是<strong>网站本身</strong>的改进。上面 v2.x 记的是<strong>游戏内框架</strong>的版本，两者是并行的两条线。</p></blockquote><p>最近一轮集中处理了可读性、移动端与安全：</p><ul><li><strong>对比度全站达标</strong>：正文与所有小字（卡片副标题、分类标签、代码块语言名）按无障碍标准（正文 4.5:1）逐项核算，深浅两套主题都验过</li><li><strong>术语统一</strong>：「悬浮球 / 悬浮窗」「声望 / 威望」「游戏里 / 游戏内」各归一处，读者不会再看到同一个东西两种叫法</li><li><strong>手机端适配</strong>：顶栏、卡片、页脚、触控目标（最小 44px）逐项重做；代码块与表格在窄屏改为容器内横向滚动，不再撑破屏幕</li><li><strong>平板断点修复</strong>：768~959px 下顶栏不再把页面撑出横向滚动条</li><li><strong>悬浮窗遮挡修复</strong>：右下角的日/夜切换按钮改为阅读时自动让路</li><li><strong>安全加固</strong>：管理员密钥改用防时序攻击的比较方式、上传接口加频率限制、跨域收紧为同源、加防点击劫持响应头</li><li><strong>性能</strong>：鼠标悬停效果改到逐帧计算（消除强制同步布局），移动端毛玻璃降级为半透明底色，字体子集化</li><li><strong>稳定性</strong>：API 服务常驻（开机自启 + 崩溃自愈），仓库页在服务不可用时回退到本地存档，不再整页空白</li></ul><hr><h2 id="v2-19-—-网页上传-审核后台" tabindex="-1">v2.19 — 网页上传 + 审核后台 <a class="header-anchor" href="#v2-19-—-网页上传-审核后台" aria-label="Permalink to &quot;v2.19 — 网页上传 + 审核后台&quot;">​</a></h2><p>把「作者要跑命令行才能发布」彻底改成「<strong>在网页上填个表就能传</strong>」，并给站长配了审核后台。</p><ul><li><strong>★ 网页上传机制</strong>：仓库页新增上传区，拖入 / 粘贴 <code>mod.json</code> → 填作者 → 提交审核。不再需要命令行脚本</li><li><strong>★ 审核后台</strong>（<code>/admin/</code>）：密钥登录，看四个指标（待审核 / 仓库在架 / 仓库总量 / 已驳回），逐条「通过并上架 / 驳回 / 下架 / 删除」，全程写操作日志</li><li><strong>★ 后端服务</strong>：零依赖 Python 脚本（只用标准库 + SQLite 单文件），负责收上传、校验、生成分享码、重建仓库清单</li><li><strong>★ 分享码解析器</strong>：网页上粘贴陌生 <code>AFMOD1:</code> 码，立刻显示这是哪个 Mod、谁写的、改了哪些参数（真的做出来了，此前文档里承诺但没实现）</li><li><strong>修掉「已上架」数字虚高</strong>：「已上架」口径改为<strong>以 <code>packages/</code> 目录为准</strong>，手工删包后后台与仓库不再对不上</li><li><strong>修掉「参数条目」永远显示 0</strong>：接口此前只认 <code>params</code> 字段，而真实 mod.json 用的是 <code>combat</code> 嵌套结构；现在会把 <code>combat.torpedo.accuracyMul</code> 这类正确展平统计</li><li><strong>示例 Mod 全面重做</strong>：原来 3 个是空壳（没有舰船 / 舰队），替换为重做后的 6 个主题 Mod（铁底湾 / 狼群 / 决斗 / 夜雾 / 沙盒 / 雷雨），每个都有完整参数 + 自定义舰船 + 自定义编队，并配了分享码</li><li><strong>视觉全面升级</strong>：海战军工风设计系统（毛玻璃、雷达扫描、光效动画），仓库页 / 后台 / 文档站统一</li><li>后端以<strong>计划任务</strong>常驻（SYSTEM 身份 + 开机自启 + 崩溃自愈），不依赖手动启动</li></ul><h2 id="v2-18-—-服务器版-mod-仓库" tabindex="-1">v2.18 — 服务器版 Mod 仓库 <a class="header-anchor" href="#v2-18-—-服务器版-mod-仓库" aria-label="Permalink to &quot;v2.18 — 服务器版 Mod 仓库&quot;">​</a></h2><p>把 Mod 分享做到「网页浏览 + 分享码导入」，不碰游戏内代码。</p><ul><li><strong>仓库站点</strong>：纯静态网页（网页 + 清单 + 可下载包），对外以 <code>http://&lt;站点地址&gt;/mods/</code> 形式提供</li><li><strong>发布工具 <code>publish_repo.py</code></strong>：一条命令上架，自动生成清单、包、分享码（<strong>已被 v2.19 的网页上传取代</strong>）</li><li><strong>网页功能</strong>：搜索 / 排序 / 详情弹层（自动列出「改了哪些参数」）/ 一键复制分享码</li><li><strong>修掉一个会让玩家下错包的真 bug</strong>：中文名 Mod 的 ASCII 别名全部退化成同一个 <code>mod</code>，导致互相覆盖。改为用名字哈希生成唯一别名，并加了发布前清空 <code>packages\\</code></li><li>纯周边：不改游戏内代码</li></ul><h2 id="v2-17-—-存档编辑页-自制模型检查" tabindex="-1">v2.17 — 存档编辑页 + 自制模型检查 <a class="header-anchor" href="#v2-17-—-存档编辑页-自制模型检查" aria-label="Permalink to &quot;v2.17 — 存档编辑页 + 自制模型检查&quot;">​</a></h2><p>回应审查里五项，逐项处置：</p><ul><li><strong>新增「存档」标签页</strong>：给进行中的战役改<strong>威望</strong>（±1千/1万，一键设 10万/50万/100万/满）和<strong>回合</strong>（±1/±10）。改的是运行时字段，保存时调用<strong>游戏自带的存档 <code>Save()</code></strong>，绝不手改二进制</li><li><strong>「跨游戏资源移植」改为「自制模型检查」</strong>：不做跨游戏扒资源（版权风险），改为列出所有已登记模型包的自检结果（在不在 / 加载成功没 / 多大）</li><li><strong>Harmony / Mod 浏览器 / 兼容矩阵</strong> → 写入 <a href="/AtlanticFleetSite/docs/roadmap">路线图</a></li><li>标签页变为 <code>参数 / Mod / 存档 / 日志 / 状态 / 帮助</code></li></ul><h2 id="v2-16-—-参数键覆盖冲突检测" tabindex="-1">v2.16 — 参数键覆盖冲突检测 <a class="header-anchor" href="#v2-16-—-参数键覆盖冲突检测" aria-label="Permalink to &quot;v2.16 — 参数键覆盖冲突检测&quot;">​</a></h2><p>把重名检测从「舰级/编队」延伸到<strong>参数层</strong>：两个 Mod 都改同一个参数时，记一条告警写明谁覆盖谁。</p><h2 id="v2-15-—-日志分级-筛选" tabindex="-1">v2.15 — 日志分级 + 筛选 <a class="header-anchor" href="#v2-15-—-日志分级-筛选" aria-label="Permalink to &quot;v2.15 — 日志分级 + 筛选&quot;">​</a></h2><p>日志分<strong>信息 / 告警 / 错误</strong>三级；「日志」页顶部加四个筛选按钮，告警行橙色、错误行红色。「复制全部日志」仍导出完整 200 条（不受筛选影响）。</p><h2 id="v2-14-—-mod-元信息-重名冲突检测" tabindex="-1">v2.14 — Mod 元信息 + 重名冲突检测 <a class="header-anchor" href="#v2-14-—-mod-元信息-重名冲突检测" aria-label="Permalink to &quot;v2.14 — Mod 元信息 + 重名冲突检测&quot;">​</a></h2><ul><li><code>mod.json</code> 顶层新增 <code>modName</code> / <code>author</code> / <code>version</code>，游戏内「Mod」页显示「作者 xxx · v1.0」</li><li><strong>跨 Mod 重名冲突检测</strong>：同名舰级 / 同名编队时记告警，写明哪两个 Mod 冲突、谁覆盖谁</li><li>「Mod」页顶部加冲突计数横幅；冲突<strong>只提示不阻止</strong></li></ul><h2 id="v2-13-—-回应文档审查" tabindex="-1">v2.13 — 回应文档审查 <a class="header-anchor" href="#v2-13-—-回应文档审查" aria-label="Permalink to &quot;v2.13 — 回应文档审查&quot;">​</a></h2><ul><li>倍速提醒条补「不影响数值」说明</li><li>分组「联机」改名「<strong>分享对战</strong>」；明确写不支持互联网联机</li><li>控制台加「<strong>重置整个 Mod 系统</strong>」（删设置/界面/临时目录，<strong>保留</strong>自制 Mod）</li></ul><h2 id="v2-12-—-记住展开分组与上次页" tabindex="-1">v2.12 — 记住展开分组与上次页 <a class="header-anchor" href="#v2-12-—-记住展开分组与上次页" aria-label="Permalink to &quot;v2.12 — 记住展开分组与上次页&quot;">​</a></h2><p>分组的展开状态、<code>openGroups</code> 与 <code>lastTab</code> 落盘到 <code>AFMOD_ui.json</code>；参数页加「全部展开 / 全部收起」。</p><h2 id="v2-11-—-常驻倍速提醒条-恢复本组" tabindex="-1">v2.11 — 常驻倍速提醒条 + 恢复本组 <a class="header-anchor" href="#v2-11-—-常驻倍速提醒条-恢复本组" aria-label="Permalink to &quot;v2.11 — 常驻倍速提醒条 + 恢复本组&quot;">​</a></h2><ul><li>顶部常驻倍速提醒条（非原速时显示、点一下回原速）——回应「点了 x2 关掉面板就忘了」</li><li>参数页每组加「<strong>恢复本组</strong>」（只还原一类，不用全清）</li></ul><h2 id="v2-10-—-游戏内「帮助」页" tabindex="-1">v2.10 — 游戏内「帮助」页 <a class="header-anchor" href="#v2-10-—-游戏内「帮助」页" aria-label="Permalink to &quot;v2.10 — 游戏内「帮助」页&quot;">​</a></h2><p>加第 5 个标签页「帮助」——<strong>大白话、零英文术语</strong>，首次安装自动弹一次。回应「看不懂」。</p><h2 id="v2-9-—-日志落盘-一键预设" tabindex="-1">v2.9 — 日志落盘 + 一键预设 <a class="header-anchor" href="#v2-9-—-日志落盘-一键预设" aria-label="Permalink to &quot;v2.9 — 日志落盘 + 一键预设&quot;">​</a></h2><ul><li>日志同步写 <code>AFMOD_log.txt</code>（每 10 条刷盘、退出补刷、超 200KB 截断）</li><li>日志页加异常计数与「复制全部日志」</li><li>参数页加四个预设（原版 / 硬核 / 爽快 / 快节奏），<strong>边界已校验</strong></li></ul><h2 id="v2-8-—-手机可读性-两处缺陷" tabindex="-1">v2.8 — 手机可读性 + 两处缺陷 <a class="header-anchor" href="#v2-8-—-手机可读性-两处缺陷" aria-label="Permalink to &quot;v2.8 — 手机可读性 + 两处缺陷&quot;">​</a></h2><ul><li>面板内放大字号 / 按钮 / 滑块把手（<strong>仅面板内、成对还原</strong>）</li><li>状态页补滚动区（原来内容溢出看不见又滚不动）</li><li>「恢复默认」改两段确认</li><li>参数行<strong>橙色</strong>标出已改项；倍速 ≠ x1 顶部橙色警示</li></ul><h2 id="v2-7-—-倍速不再跨重启保留" tabindex="-1">v2.7 — 倍速不再跨重启保留 <a class="header-anchor" href="#v2-7-—-倍速不再跨重启保留" aria-label="Permalink to &quot;v2.7 — 倍速不再跨重启保留&quot;">​</a></h2><p><strong>真机反馈</strong>：「总感觉什么速率都变快了」。</p><p>根因：<code>sandbox.timeScale</code> 被落盘持久化，重启仍是 x2/x3，而 <code>Time.timeScale</code> 管辖一切时间推进。</p><p>修复：启动强制回 <code>x1</code>（<strong>仅本次会话有效</strong>）；状态页加「偏离原版的参数」清单。</p><h2 id="v2-6-—-悬浮窗点不动修复" tabindex="-1">v2.6 — 悬浮窗点不动修复 <a class="header-anchor" href="#v2-6-—-悬浮窗点不动修复" aria-label="Permalink to &quot;v2.6 — 悬浮窗点不动修复&quot;">​</a></h2><p><strong>真机反馈</strong>：「最小化后打不开、点不动」。四个根因一次全修：</p><ol><li>删掉「长按 0.3 秒」门槛（恢复点按即开）</li><li>位移阈值 <code>TapSlop()</code> 按屏宽 2% 取（不再用鼠标的 6px）</li><li>圆点放大到 34px 且<strong>判定区外扩</strong></li><li>MouseUp 超时兜底 + <strong>三指手势强开</strong></li></ol><p>点击判定状态机 10/10 单测通过。</p><h2 id="v2-5-—-「状态」页探针" tabindex="-1">v2.5 — 「状态」页探针 <a class="header-anchor" href="#v2-5-—-「状态」页探针" aria-label="Permalink to &quot;v2.5 — 「状态」页探针&quot;">​</a></h2><p>新增「状态」标签页，每 0.5 秒读战斗现场（回合 / 是否玩家回合 / 主炮装填门数 / 鱼雷装填管数 / 倍速），不再靠猜。</p><h2 id="v2-4-—-排查「点发射后什么都没了」" tabindex="-1">v2.4 — 排查「点发射后什么都没了」 <a class="header-anchor" href="#v2-4-—-排查「点发射后什么都没了」" aria-label="Permalink to &quot;v2.4 — 排查「点发射后什么都没了」&quot;">​</a></h2><p>排除式排查：排除汉化误译、排除伤害倍率归零、排除日志回调冲突。</p><p>新增 <code>ModLogHook.cs</code>：Unity 引擎 Error/Exception/Assert 自动进日志页，异常风暴限流。</p><h2 id="v2-3-—-真机反馈修复" tabindex="-1">v2.3 — 真机反馈修复 <a class="header-anchor" href="#v2-3-—-真机反馈修复" aria-label="Permalink to &quot;v2.3 — 真机反馈修复&quot;">​</a></h2><ol><li>悬浮窗默认位置从<strong>右下角</strong>改<strong>顶部居中</strong>（原位置压住战斗射击按钮）</li><li>倍速循环<strong>去掉暂停档</strong>（误触 x0 会让所有协程冻结像死机）；timeScale 为 0 时按钮变红警示</li><li>加「长按 0.3 秒防误触」门槛、面板真悬浮窗化（点外收起、标题栏拖动）、参数行中文化 <blockquote><p>⚠️ 长按门槛在 v2.6 被<strong>移除</strong>——它导致玩家完全打不开面板</p></blockquote></li></ol><h2 id="v2-2-—-悬浮窗倍速快捷键" tabindex="-1">v2.2 — 悬浮窗倍速快捷键 <a class="header-anchor" href="#v2-2-—-悬浮窗倍速快捷键" aria-label="Permalink to &quot;v2.2 — 悬浮窗倍速快捷键&quot;">​</a></h2><p>「小u」右侧加 <code>x1</code> 按钮，点一下循环 x1→x2→x3→x1（当时还含暂停档）。落盘 <code>AFMOD_settings.json</code>。</p><h2 id="v2-1-—-mod-管理中心" tabindex="-1">v2.1 — Mod 管理中心 <a class="header-anchor" href="#v2-1-—-mod-管理中心" aria-label="Permalink to &quot;v2.1 — Mod 管理中心&quot;">​</a></h2><p>补「Mod / 日志」两个标签页：列出已装 Mod、禁用/启用（写 <code>_disabled.txt</code>）、一键分享码、删除（二次确认）；日志页显示最近 200 条带时间戳。</p><h2 id="v2-0-—-游戏内-mod-控制台" tabindex="-1">v2.0 — 游戏内 Mod 控制台 <a class="header-anchor" href="#v2-0-—-游戏内-mod-控制台" aria-label="Permalink to &quot;v2.0 — 游戏内 Mod 控制台&quot;">​</a></h2><p>把「创意工坊」做成手机上可用的工具：半透明可拖动悬浮窗「小u」+ 面板，玩家不手改 JSON 就能看/调全部参数。零 prefab 依赖，任何异常只记日志不崩游戏。</p><hr><h2 id="★-作者自我更正" tabindex="-1">★ 作者自我更正 <a class="header-anchor" href="#★-作者自我更正" aria-label="Permalink to &quot;★ 作者自我更正&quot;">​</a></h2><p>保留在此，便于后人少走弯路。</p><h3 id="_1-「主炮按轮装填」——-作废" tabindex="-1">① 「主炮按轮装填」—— 作废 <a class="header-anchor" href="#_1-「主炮按轮装填」——-作废" aria-label="Permalink to &quot;① 「主炮按轮装填」—— 作废&quot;">​</a></h3><p><strong>曾写过</strong>：「主炮装填按轮计，所以第 2 轮点发射没反应」。</p><p><strong>正确规则</strong>：<strong>主炮每回合都可以炮击，只有鱼雷才每回合装填一发</strong>（<code>turnsToReload</code> 只对鱼雷生效）。</p><p>所以「第 2 轮打不出去」<strong>不是机制，是真缺陷</strong>。</p><h3 id="_2-「悬浮窗吞点击」——-解释不成立" tabindex="-1">② 「悬浮窗吞点击」—— 解释不成立 <a class="header-anchor" href="#_2-「悬浮窗吞点击」——-解释不成立" aria-label="Permalink to &quot;② 「悬浮窗吞点击」—— 解释不成立&quot;">​</a></h3><p><strong>曾推测</strong>：悬浮窗挡住了射击按钮导致点不动。</p><p><strong>源码核查</strong>：战斗 UI 走 <strong>NGUI</strong>，用 <code>Input.GetMouseButton*</code> / <code>Input.touchCount</code> <strong>轮询</strong>，不依赖 OnGUI 的 <code>Event.current</code>。所以在悬浮窗里调 <code>e.Use()</code> <strong>拦不住</strong> NGUI 按钮——两者是两套独立输入管线。</p><p><strong>结论</strong>：把悬浮窗挪到顶部仍有价值（视觉上不再盖住按钮），但<strong>不是</strong>「点射击没反应」的修复。</p><p>该现象的真因嫌疑是 <strong>x3 倍速时的时序问题</strong>（开火/装填/动画都 3 倍速推进，玩家没看清就进了敌方回合，观感正是「点了发射后什么都没了」）。</p><blockquote><p>这也正是 v2.7 把倍速改成「仅本次会话有效」的背景。</p></blockquote><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>以后可能加什么 → <a href="/AtlanticFleetSite/docs/roadmap">路线图</a></li><li>技术原理 → <a href="/AtlanticFleetSite/docs/technical">技术细节</a></li><li>名词看不懂 → <a href="/AtlanticFleetSite/docs/glossary">术语表</a></li></ul>',71)])])}const p=a(l,[["render",n]]);export{u as __pageData,p as default};
